pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(0) && target != address(c));
        vm.deal(address(this), 1 ether);

        payable(address(c)).transfer(1 ether);

        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        vm.assume(success);

        // After sendMoney, the contract balance may have changed. The withdrawAll call will use balance + 1 in the mutant.
        // We check that the result of calling withdrawAll (which eventually calls withdraw) is consistent with the original contract.
        // Actually we need a general rule that holds for reference and breaks for mutant.
        // Rule: after sendMoney, calling withdrawAll should always reduce contract balance to 0 (since owner receives it).
        uint256 balanceBefore = address(c).balance;
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        // The general rule: after withdrawAll, contract balance should be 0.
        assertTrue(balanceAfter == 0);
    }
}

