import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Restrict value to avoid overflow in balance check
        vm.assume(value <= address(c).balance / 2);

        // Perform a state-modifying call that may increase contract balance
        (bool successSend, ) = address(c).call{value: value}(data);

        // Record balance before withdrawAll
        uint256 balanceBefore = address(c).balance;

        // Call withdrawAll
        c.withdrawAll();

        // After withdrawAll, contract balance should be zero if sendMoney succeeded
        // because withdrawAll transfers all balance to owner.
        // If sendMoney failed (reverted), balance remains unchanged.
        bool property = successSend ? address(c).balance == 0 : address(c).balance == balanceBefore;
        assertTrue(property);
    }

    // Helper to allow sending ether to contract via fallback
    receive() external payable {}
}

