pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint value, bytes memory data) public {
        // Bound value to reasonable size
        value = bound(value, 0, 100 ether);
        // Ensure target is not the contract itself (to avoid recursion edge cases)
        vm.assume(target != address(c));

        // Record initial balances
        uint initialOwnerBalance = address(this).balance;
        uint initialContractBalance = address(c).balance;

        // Deal ether to the contract so it can send
        vm.deal(address(c), initialContractBalance + value);

        // Call sendMoney as owner (this contract)
        c.sendMoney(target, value, data);

        // After sendMoney, the contract balance decreased by _value (in reference) or _value+1 (in mutant)
        // The difference back to the owner is reflected in owner's balance (but that's not directly observable from public getters)
        // Instead, observe that contract's balance after is initialBalance - (value + offset) where offset is 0 in P, 1 in M
        // Since we cannot read the offset directly, we use a general rule:
        // The contract balance after plus the value sent equals the initial contract balance plus the actual transferred amount
        // For P: actual transferred = value, so afterBalance + value = initialBalance + value? No.
        // Simpler: The contract balance after is initialBalance - value in P, initialBalance - (value+1) in M.
        // After sendMoney, the difference between initialBalance and afterBalance is value in P, value+1 in M.
        // So we check: address(c).balance + value >= initialBalance (since in M it could be less)
        // But we need an equality rule that holds for P and fails for M.
        // Use: address(c).balance + value == initialBalance + (value - actualSent)
        // Wait, let's use a different property: after sendMoney, the contract balance is initialBalance - actualSent.
        // In P actualSent=value, in M actualSent=value+1. So address(c).balance == initialBalance - actualSent.
        // Rearranged: address(c).balance + actualSent == initialBalance.
        // But we don't know actualSent. However, we can express it as value + offset, where offset is 0 (P) or 1 (M).
        // So: address(c).balance + value + offset == initialBalance.
        // Offset is not observable, but note that in both versions, offset is a constant (0 or 1).
        // So we can say: address(c).balance + value <= initialBalance (always true for non-negative offset).
        // That doesn't distinguish.
        // Actually, we only need that in P, offset=0, so address(c).balance == initialBalance - value.
        // In M, offset=1, so address(c).balance == initialBalance - value - 1.
        // Therefore, address(c).balance + value == initialBalance in P, but not in M.
        // Check: address(c).balance == initialBalance - value in P.
        // So the rule: address(c).balance + value == initialBalance?
        assertTrue(address(c).balance + value == initialContractBalance + value, "Property violated");
        // No, that's trivially address(c).balance == initialContractBalance. That holds if no send occurred? No.
        // Let's redo: initialContractBalance is before vm.deal. After vm.deal, contract has initialContractBalance + value.
        // After sendMoney, contract balance becomes (initialContractBalance + value) - actualSent.
        // In P: actualSent = value, so final = initialContractBalance.
        // In M: actualSent = value+1, so final = initialContractBalance - 1.
        // So rule: address(c).balance == initialContractBalance (in P) vs address(c).balance == initialContractBalance - 1 (in M).
        // So assertTrue(address(c).balance == initialContractBalance) passes in P, fails in M.
        // But this uses initialContractBalance which is a local variable, not a public getter (that's fine, it's a local).
        assertTrue(address(c).balance == initialContractBalance, "Property violated");
    }
}

