        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(0), amount, emptyData));
        uint256 after = c.depositsCount();
        assertTrue(success == (after == before + (amount > 0 ? 1 : 0)));
    }
}
